const ELEMENT_PROP_KEYS = new Set(["theme","left","right","caption","joiner","fontWeight","trail","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  left: "remocn",
  right: "Kitebase",
  caption: "Launch videos, rendered from every Kitebase workspace.",
  joiner: "×",
  fontWeight: 500,
  trail: true,
  accent: "#3B5BFD",
  fontFamily: "Manrope",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type CollabLockupElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof CollabLockupBase>;

const CollabLockupInner = forwardRef<
  HTMLDivElement,
  CollabLockupElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<CollabLockup>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <CollabLockupBase
          {...(componentProps as unknown as ComponentProps<typeof CollabLockupBase>)}
        />
      </div>
    </Sequence>
  );
});

export const CollabLockup = Interactive.withSchema({
